export function parseRange(text) {
  const parts = String(text).split('-').map((part) => Number(part.trim()));
  if (parts.length > 2 || parts.some((n) => !Number.isInteger(n))) {
    throw new TypeError(`invalid range: ${text}`);
  }
  // A single value is a one-element range, not an unbounded one.
  const [start, end = start] = parts;
  if (end < start) {
    throw new RangeError(`range ends before it starts: ${text}`);
  }
  // end is inclusive, matching what callers expect.
  return { start, end };
}

