index f5c4957..e3f3b97 100644
--- a/src/parser.mjs
+++ b/src/parser.mjs
@@ -1,5 +1,13 @@
 export function parseRange(text) {
-  const [start, end] = text.split('-').map(Number);
-  // end is exclusive here, which is not what callers expect
-  return { start, end: end + 1 };
+  const parts = String(text).split('-').map((part) => Number(part.trim()));
+  if (parts.length > 2 || parts.some((n) => !Number.isInteger(n))) {
+    throw new TypeError(`invalid range: ${text}`);
+  }
+  // A single value is a one-element range, not an unbounded one.
+  const [start, end = start] = parts;
+  if (end < start) {
+    throw new RangeError(`range ends before it starts: ${text}`);
+  }
+  // end is inclusive, matching what callers expect.
+  return { start, end };
 }
```

`git.diff` 汇总：1 个文件，+11 / -3，状态 `modified`；`git.status` 显示工作区只有这一处改动。

## 需要你知道的两点

1. **我没能实际跑测试验证。** 这个后端禁止启动进程（`shell.run` 被 policy 拒绝，risk l3，需要 `AGENT_SANDBOX=app-container`），所以上面的行为描述是我根据代码推断的，不是跑出来的结果。如果你能给我一个可以执行命令的环境，我可以补一个最小验证。
2. **语义变更会影响现有调用方：** `end` 从「独占 + 偏移」变成「闭区间」，这是修 bug 的正确方向，但如果仓库外有依赖旧行为的代码，需要同步检查。仓库内我 grep 过，`parseRange` 没有其他调用点。

如果你其实更希望保持 `end` 左闭右开（很多 JS 切片 API 是这种约定），告诉我，我改成只删掉 `+1`、并在注释里显式写明半开区间的版本。

